275	/// Errors returned by model resolution and provider calls.
276	#[derive(Error, Debug)]
277	#[non_exhaustive]
278	pub enum ModelError {
279	    /// The requested model name is not present in config.
280	    #[error("no such model: {0}")]
281	    UnknownModel(String),
282	    /// The requested role name is not present in config.
283	    #[error("no such role: {0}")]
284	    UnknownRole(String),
285	    /// The requested provider is not registered.
286	    #[error("no such provider: {0}")]
287	    UnknownProvider(String),
288	    /// A provider credential is required but absent.
289	    #[error("missing credential for provider {provider}: env var {env_var} not set")]
290	    MissingCredential {
291	        /// Provider that requires the credential.
292	        provider: String,
293	        /// Missing environment variable name.
294	        env_var: String,
295	    },
296	    /// A provider call exceeded its configured timeout.
297	    #[error("timeout after {seconds}s calling {provider}")]
298	    Timeout {
299	        /// Provider that timed out.
300	        provider: String,
301	        /// Timeout in whole seconds.
302	        seconds: u64,
303	    },
304	    /// A provider returned an error.
305	    #[error("provider error ({provider}): {message}")]
306	    Provider {
307	        /// Provider that returned the error.
308	        provider: String,
309	        /// Provider error message.
310	        message: String,
311	        /// Whether the caller may retry the request.
312	        retryable: bool,
313	    },
314	    /// A configured model is invalid.
315	    #[error("invalid model config for {model}: {message}")]
316	    InvalidConfig {
317	        /// Configured model name.
318	        model: String,
319	        /// Validation message.
320	        message: String,
321	    },
322	}
323	
324	impl ModelError {
325	    /// Returns whether the error is retryable.
326	    pub fn is_retryable(&self) -> bool {
327	        match self {
328	            Self::Timeout { .. } => true,
329	            Self::Provider { retryable, .. } => *retryable,
330	            Self::UnknownModel(_)
331	            | Self::UnknownRole(_)
332	            | Self::UnknownProvider(_)
333	            | Self::MissingCredential { .. }
334	            | Self::InvalidConfig { .. } => false,
335	        }
336	    }
337	}
338	
339	type ProviderConstructor =
340	    Arc<dyn Fn(&ModelDef, &AuthStore) -> Result<Box<dyn Model>, ModelError> + Send + Sync>;
341	
342	/// Registry mapping provider names to model constructors.
343	#[derive(Clone, Default)]
344	pub struct ProviderRegistry {
345	    constructors: HashMap<String, ProviderConstructor>,
346	}
347	
348	impl ProviderRegistry {
349	    /// Returns a registry pre-populated with T006 providers.
350	    pub fn with_defaults() -> Self {
351	        let mut registry = Self::default();
352	        registry.register("shell", providers::shell::build);
353	        registry.register("anthropic", providers::anthropic::build);
354	        registry.register("openai-cli", providers::openai_cli::build);
355	        registry.register("opencode", providers::opencode::build);
356	        registry
357	    }
358	
359	    /// Adds or replaces a constructor for a provider name.
360	    pub fn register<F>(&mut self, name: &str, constructor: F)
361	    where
362	        F: Fn(&ModelDef, &AuthStore) -> Result<Box<dyn Model>, ModelError> + Send + Sync + 'static,
363	    {
364	        self.constructors
365	            .insert(name.to_owned(), Arc::new(constructor));
366	    }
367	
368	    /// Builds a model from a model definition.
369	    pub fn build(
370	        &self,
371	        model_def: &ModelDef,
372	        auth: &AuthStore,
373	    ) -> Result<Box<dyn Model>, ModelError> {
374	        let provider = model_def.provider();
375	        let constructor = self
376	            .constructors
377	            .get(provider)
378	            .ok_or_else(|| ModelError::UnknownProvider(provider.to_owned()))?;
379	
380	        constructor(model_def, auth)
381	    }
382	}
383	
384	/// Resolves a role name to a ready-to-call model.
385	pub async fn resolve_role(
386	    role: &str,
387	    roles: &RoleBindings,
388	    models: &ModelRegistry,
389	    auth: &AuthStore,
390	) -> Result<Box<dyn Model>, ModelError> {
391	    let model_name = roles
392	        .get(role)
393	        .ok_or_else(|| ModelError::UnknownRole(role.to_owned()))?;
394	    let model_def = models
395	        .get(model_name)
396	        .ok_or_else(|| ModelError::UnknownModel(model_name.to_owned()))?;
397	
398	    ProviderRegistry::with_defaults().build(model_def, auth)
399	}
