        &self,
        model_def: &ModelDef,
        auth: &AuthStore,
    ) -> Result<Box<dyn Model>, ModelError> {
        let provider = model_def.provider();
        let constructor = self
            .constructors
            .get(provider)
            .ok_or_else(|| ModelError::UnknownProvider(provider.to_owned()))?;

