120	mod tests {
121	    use super::parse_claude_json;
122	
123	    #[test]
124	    fn parse_claude_json_extracts_result_and_tokens() {
125	        let raw = r#"{
126	            "type": "result",
127	            "subtype": "success",
128	            "is_error": false,
129	            "result": "Hello, world!",
130	            "session_id": "abc",
131	            "num_turns": 1,
132	            "total_cost_usd": 0.001,
133	            "usage": {
134	                "input_tokens": 42,
135	                "output_tokens": 7,
136	                "cache_read_input_tokens": 0,
137	                "cache_creation_input_tokens": 0
138	            }
139	        }"#;
140	        let (text, tokens_in, tokens_out) = parse_claude_json(raw);
141	        assert_eq!(text, "Hello, world!");
142	        assert_eq!(tokens_in, 42);
143	        assert_eq!(tokens_out, 7);
144	    }
145	
146	    #[test]
147	    fn parse_claude_json_falls_back_on_plain_text() {
148	        let raw = "This is a plain text response";
149	        let (text, tokens_in, tokens_out) = parse_claude_json(raw);
150	        assert_eq!(text, raw);
151	        assert_eq!(tokens_in, 0);
152	        assert_eq!(tokens_out, 0);
153	    }
154	
155	    #[test]
156	    fn parse_claude_json_handles_missing_usage() {
157	        let raw = r#"{"result": "hi", "type": "result"}"#;
158	        let (text, tokens_in, tokens_out) = parse_claude_json(raw);
159	        assert_eq!(text, "hi");
160	        assert_eq!(tokens_in, 0);
161	        assert_eq!(tokens_out, 0);
162	    }
